#include "mesh.h"#include "FileStuff.h"void putHeight ( FSSpec &theMeshFSSpec );long doDialog( short newDialog );void putHeight ( FSSpec &theMeshFSSpec ){//----------------------------------vars--------------------------------------------------	short		theMeshFileRef, theMapFileRef;	Str255		theMapFileName = "\p:Graphics.in:elevation.bmp";	OSErr		theError;	FSSpec		theMapFSSpec;	const short rHeightInputDialog = 130;	long factor;	char meshFolder[48] = ":mesh.out:";	unsigned char *TheMap;	int i, x, y;	long meshSize, meshWidth, meshHeight;	struct meshHeader theMeshHeader;	struct gridData *theGrid;//----------------------------------------------------------------------------------------		factor =  doDialog( rHeightInputDialog );	if ( factor == 0 )		return;	theError = FSpOpenDF ( &theMeshFSSpec, fsCurPerm, &theMeshFileRef );	if ( theError != noErr ){		ParamText( "\pCan't open mesh file.", "\p", "\p", "\p" );		StopAlert ( 400, nil );		ExitToShell();	}	FileRead ( &theMeshHeader, sizeof(struct meshHeader), theMeshFileRef );	meshWidth = theMeshHeader.meshWidth * 16;	meshHeight = theMeshHeader.meshHeight * 16;	meshSize =  meshWidth * meshHeight;	theGrid = (struct gridData *) NewPtr (meshSize * sizeof(gridData));	FileRead(theGrid, theMeshHeader.meshLength, theMeshFileRef);	theError = FSMakeFSSpec (0, 0, theMapFileName, &theMapFSSpec);	theError = FSpOpenDF ( &theMapFSSpec, fsCurPerm, &theMapFileRef );	if ( theError != noErr ){		ParamText( "\pCan't open elevation.bmp.", "\p", "\p", "\p" );		StopAlert ( 400, nil );		ExitToShell();	}	TheMap = (unsigned char *) NewPtr ( meshSize );	FileSeek ( theMapFileRef, 1078L );	FileRead(TheMap, meshSize, theMapFileRef);	FSClose ( theMapFileRef );		for ( y = meshHeight - 1, i = 0; y >= 0; y-- )		for ( x = meshWidth - 1; x >= 0; x--, i++ )				theGrid[i].height -= TheMap[x + y * meshWidth] * factor;	FileSeek ( theMeshFileRef, 1088L );	FileWrite (theGrid, theMeshHeader.meshLength, theMeshFileRef);	DisposePtr ( (Ptr) TheMap );	DisposePtr ( (Ptr) theGrid );	FSClose ( theMeshFileRef );}